'use strict';

const grep = require('./utils/grep');

class Evaluator {
  #projectFiles;
  #nonSourceFiles;
  #fileCache;
  #cdsEnvOutput;

  constructor(projectFiles, nonSourceFiles, fileCache, cdsEnvOutput) {
    this.#projectFiles = projectFiles;
    this.#nonSourceFiles = nonSourceFiles;
    this.#fileCache = fileCache;
    this.#cdsEnvOutput = cdsEnvOutput;
  }

  evaluateRules(rules) {
    return rules.map((rule) => {
      const matches = [];
      this.#collectSourceMatches(rule, matches);
      this.#collectCdlMatches(rule, matches);
      this.#collectCdsEnvMatches(rule, matches);
      this.#collectOtherMatches(rule, matches);
      return { rule, matches };
    });
  }

  #collectSourceMatches(rule, matches) {
    if (!rule.patternSource) return;
    matches.push(...grep.grepCached(rule.patternSource, this.#projectFiles.source, this.#fileCache));
  }

  #collectCdlMatches(rule, matches) {
    if (!rule.patternCdl) return;
    for (const pattern of rule.patternCdl) {
      matches.push(...grep.grepCached(pattern, this.#projectFiles.cdl, this.#fileCache));
    }
  }

  #collectCdsEnvMatches(rule, matches) {
    if (!rule.patternCdsEnv) return;
    for (const pattern of rule.patternCdsEnv) {
      const envMatches = this.#cdsEnvOutput
        ? grep.grepText(pattern, this.#cdsEnvOutput, '<cds env>')
        : [];
      const leaf = grep.extractLeafPattern(pattern);
      const fileMatches = grep.grepCached(leaf, this.#projectFiles.config, this.#fileCache);
      let raw = fileMatches.length ? fileMatches : envMatches;

      if (rule.defaultValue !== undefined && raw.length) {
        raw = filterByConfigValue(raw, rule);
      }

      matches.push(...raw);
    }
  }

  #collectOtherMatches(rule, matches) {
    if (!rule.patternOther) return;
    for (const pattern of rule.patternOther) {
      matches.push(...grep.grepCached(pattern, this.#nonSourceFiles, this.#fileCache));
    }
  }
}

function filterByConfigValue(matches, rule) {
  return matches.filter(m => {
    const value = extractConfigValue(m);
    if (value === null) return true;
    const isRemoved = rule.capireSection === 'Flags Entirely Removed';
    if (!isRemoved) return false;
    const isDefault = String(value) === String(rule.defaultValue);
    m.valueStatus = isDefault ? 'default' : 'killswitch';
    return true;
  });
}

function extractConfigValue(match) {
  const lineIdx = Math.min(3, match.line - 1);
  const line = match.surroundingLines?.[lineIdx];
  if (!line) return null;
  const valueMatch = line.match(/[=:]\s*(.+?)[\s,}]*$/);
  if (!valueMatch) return null;
  const raw = valueMatch[1].trim().replace(/^["']|["']$/g, '');
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  return raw;
}

module.exports = Evaluator;
